#!/bin/bash
# Offline validation of the customized rootfs (run on the build host, as root).
set -uo pipefail
R="${1:?usage: validate.sh <rootfs>}"
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
pass=0; fail=0
ok()  { echo "PASS  $*"; pass=$((pass+1)); }
bad() { echo "FAIL  $*"; fail=$((fail+1)); }
chk() { local d="$1"; shift; if "$@" >/dev/null 2>&1; then ok "$d"; else bad "$d"; fi; }
inr() { chroot "$R" /usr/bin/env LC_ALL=C "$@"; }

for p in sddm openbox zenity openssh-server avahi-daemon steam-devices vulkan-tools \
         pkexec polkitd systemd-zram-generator earlyoom xfce4 xwayland tailscale nvidia-l4t-core nvidia-l4t-3d-core; do
  # shellcheck disable=SC2016
  chk "package installed: $p" bash -c "chroot '$R' dpkg-query -W -f='\${Status}' '$p' | grep -q 'install ok installed'"
done
for u in sddm ssh avahi-daemon steamos-orin-firstboot steamos-orin-maxn-super earlyoom steamos-orin-oom-tagger steamos-orin-swapfile; do
  chk "service enabled: $u" bash -c "chroot '$R' systemctl is-enabled $u.service | grep -q enabled"
done
for u in systemd-timesyncd systemd-time-wait-sync; do
  chk "service enabled: $u" bash -c "chroot '$R' systemctl is-enabled $u.service | grep -q enabled"
done
chk "firstboot ordered after time-sync.target" grep -q '^After=.*time-sync.target' "$R/etc/systemd/system/steamos-orin-firstboot.service"
chk "timesync clock file seeded (no 1970 boots)" test -e "$R/var/lib/systemd/timesync/clock"
chk "nvfb-swapfile disabled + never-true condition drop-in" bash -c "! chroot '$R' systemctl is-enabled nvfb-swapfile.service 2>/dev/null | grep -qx enabled && grep -q enable-nvfb-swapfile '$R/etc/systemd/system/nvfb-swapfile.service.d/10-steamos-orin-disable.conf'"
for u in iperf3.service saned.socket systemd-networkd-wait-online.service; do
  chk "masked: $u" bash -c "chroot '$R' systemctl is-enabled $u 2>/dev/null | grep -qx masked"
done
chk "no stock /swapfile in image or fstab" bash -c "[ ! -e '$R/swapfile' ] && ! grep -q '^/swapfile' '$R/etc/fstab'"
chk "netplan files mode 600" bash -c "for f in '$R'/etc/netplan/*.yaml; do [ -e \"\$f\" ] || continue; [ \$(stat -c %a \"\$f\") = 600 ] || exit 1; done"
chk "tailscaled NOT enabled" bash -c "! chroot '$R' systemctl is-enabled tailscaled.service 2>/dev/null | grep -q '^enabled'"
chk "tailscale has no state/auth" bash -c "[ ! -s '$R/var/lib/tailscale/tailscaled.state' ]"
chk "display-manager -> sddm" bash -c "readlink '$R/etc/systemd/system/display-manager.service' | grep -q sddm"
chk "default target graphical" bash -c "chroot '$R' systemctl get-default | grep -q graphical"
chk "hostname orin-steamos" grep -qx orin-steamos "$R/etc/hostname"
chk "user steamos exists" inr id steamos
chk "steamos in sudo group" bash -c "chroot '$R' id -nG steamos | grep -qw sudo"
chk "steamos in input,video,render" bash -c "g=\$(chroot '$R' id -nG steamos); for x in input video render; do echo \$g | grep -qw \$x || exit 1; done"
chk "authorized_keys perms 600" bash -c "[ \$(stat -c %a '$R/home/steamos/.ssh/authorized_keys') = 600 ]"
chk ".ssh perms 700" bash -c "[ \$(stat -c %a '$R/home/steamos/.ssh') = 700 ]"
chk "authorized_keys owned by steamos" bash -c "[ \$(chroot '$R' stat -c %U /home/steamos/.ssh/authorized_keys) = steamos ]"
chk "sshd config parses (sshd -t)" bash -c "mkdir -p '$R/run/sshd'; chroot '$R' bash -c 'ssh-keygen -A >/dev/null 2>&1; /usr/sbin/sshd -t'"
chk "sshd PasswordAuthentication no" bash -c "chroot '$R' bash -c '/usr/sbin/sshd -T 2>/dev/null' | grep -qx 'passwordauthentication no'"
chk "sshd PermitRootLogin no" bash -c "chroot '$R' bash -c '/usr/sbin/sshd -T 2>/dev/null' | grep -qx 'permitrootlogin no'"
# Host keys generated by validation must not ship: regenerate on first boot
rm -f "$R"/etc/ssh/ssh_host_*
chk "ssh host keys regenerate on boot (sshd-keygen/ssh.service)" bash -c "grep -rqs 'ssh-keygen -A' '$R/usr/lib/systemd/system/' '$R/etc/systemd/system/' || [ -e '$R/usr/lib/systemd/system/ssh.service' ]"
chk "sddm autologin conf parses" python3 -c "import configparser,sys;c=configparser.ConfigParser();c.read('$R/etc/sddm.conf.d/10-steamos.conf');assert c['Autologin']['User']=='steamos' and c['Autologin']['Session']=='steam-gamescope.desktop'"
for f in usr/share/xsessions/steam-gamemode.desktop usr/share/wayland-sessions/steam-gamescope.desktop \
         usr/share/applications/steamos-return-to-gamemode.desktop; do
  # Session files use DesktopNames (standard for display managers, unknown to desktop-file-validate)
  if command -v desktop-file-validate >/dev/null && [[ $f == usr/share/applications/* ]]; then chk "desktop-file-validate $f" desktop-file-validate "$R/$f"
  else chk "desktop file parses $f" python3 -c "import configparser;c=configparser.ConfigParser(interpolation=None);c.read('$R/$f');assert 'Exec' in c['Desktop Entry']"; fi
done
chk "xfce session present" test -f "$R/usr/share/xsessions/xfce.desktop"
chk "systemd units verify" bash -c "chroot '$R' systemd-analyze verify /etc/systemd/system/steamos-orin-firstboot.service /etc/systemd/system/steamos-orin-maxn-super.service /etc/systemd/system/steamos-orin-oom-tagger.service /etc/systemd/system/steamos-orin-swapfile.service /etc/systemd/system/steamos-orin-session-reset.service /etc/systemd/system/var-swap-swapfile.swap 2>&1 | grep -vE 'Failed to (connect|open)|not running|loading' | grep -qiE 'error|invalid' && exit 1 || exit 0"
chk "udev rules parse (udevadm verify)" bash -c "chroot '$R' udevadm verify /etc/udev/rules.d/60-steamos-orin-input.rules"
if command -v node >/dev/null; then chk "polkit rules behave (mock polkit test)" node "$HERE/scripts/test-polkit-rules.js" "$R/etc/polkit-1/rules.d/49-steamos-orin.rules"
else chk "polkit rules file present" test -s "$R/etc/polkit-1/rules.d/49-steamos-orin.rules"; fi
chk "uinput autoload" grep -qx uinput "$R/etc/modules-load.d/steamos-orin.conf"
if [[ ${WITH_INPUT_MODULES:-1} == 1 ]]; then
  KREL="$(find "$R/lib/modules" -mindepth 1 -maxdepth 1 -printf "%f\n" | sort -V | tail -1)"
  for m in uinput hid-steam hid-playstation hid-nintendo hid-sony; do
    chk "kernel module $m built for $KREL (vermagic)" bash -c "chroot '$R' modinfo -k '$KREL' -F vermagic $m | grep -q '^$KREL '"
  done
  chk "hid-steam alias registered (Valve 28DE)" bash -c "grep -qi 'hid_steam' '$R/lib/modules/$KREL/modules.alias'"
fi
chk "steam-devices udev rules" bash -c "ls '$R'/usr/lib/udev/rules.d/*steam* >/dev/null"
chk "quiet boot in extlinux" grep -q 'quiet' "$R/boot/extlinux/extlinux.conf"
if [[ $(sed -n 's/^PREINSTALL_STEAM=\([01]\).*/\1/p' "$R/etc/steamos-orin/build-info" 2>/dev/null) == 1 ]]; then
  chk "Steam preinstalled (steamrtarm64/steam + stamp, owned by steamos)" bash -c "[ -x '$R/home/steamos/.local/share/Steam/steamrtarm64/steam' ] && [ -f '$R/home/steamos/.local/share/Steam/.steamos-orin-installed' ] && [ \$(chroot '$R' stat -c %U /home/steamos/.local/share/Steam/steamrtarm64/steam) = steamos ]"
  chk "Steam preinstall has no backslash paths left" bash -c "! find '$R/home/steamos/.local/share/Steam' -maxdepth 1 -name '*\\\\*' | grep -q ."
else
  chk "no Steam binaries shipped (PREINSTALL_STEAM=0)" bash -c "! find '$R/home' '$R/opt' -path '*steamrtarm64*' | grep -q ."
fi
chk "no steamrt64 -> steamrtarm64 alias" bash -c "[ ! -L '$R/home/steamos/.local/share/Steam/steamrt64' ]"
chk "session scripts never make the desktop sticky automatically" bash -c "! grep -n 'steamos-session-select desktop' '$R/usr/lib/steamos-orin/steam-gamemode-session' '$R/usr/lib/steamos-orin/firstboot-setup'"
chk "service enabled: steamos-orin-session-reset" bash -c "chroot '$R' systemctl is-enabled steamos-orin-session-reset.service | grep -q enabled"
chk "oneshot desktop: set-session marks + boot reset removes" bash -c "d=\$(mktemp -d); printf '# steamos-orin: oneshot\n[Autologin]\nSession=xfce.desktop\n' > \$d/c; sed 's#/etc/sddm.conf.d/zz-steamos-autologin.conf#'\$d'/c#' '$R/usr/lib/steamos-orin/session-reset-boot' | bash >/dev/null; r=0; [ -e \$d/c ] && r=1; rm -rf \$d; exit \$r"
chk "Return to Gaming Mode launcher on the Desktop" test -x "$R/home/steamos/Desktop/steamos-return-to-gamemode.desktop"
chk "steamos-update stub reports 'no update' (exit 7)" bash -c "'$R/usr/bin/steamos-update' check >/dev/null; [ \$? -eq 7 ]"
chk "jupiter-biosupdate stub exits 0" "$R/usr/bin/jupiter-biosupdate"
chk "session-select: plasma=one-time desktop, desktop/plasma-persistent=persistent" bash -c "grep -q '^    plasma)' '$R/usr/bin/steamos-session-select' && grep -q 'plasma-persistent' '$R/usr/bin/steamos-session-select'"
chk "wireplumber: ALSA sinks never suspend (0.4 lua + 0.5 conf)" bash -c "grep -q 'session.suspend-timeout-seconds\"\] = 0' '$R/etc/wireplumber/main.lua.d/51-steamos-orin-no-suspend.lua' && grep -q 'session.suspend-timeout-seconds = 0' '$R/etc/wireplumber/wireplumber.conf.d/51-steamos-orin-no-suspend.conf'"
chk "zram-generator config" test -f "$R/etc/systemd/zram-generator.conf"
# --- OOM hardening ---
chk "swap unit enabled: var-swap-swapfile.swap" bash -c "chroot '$R' systemctl is-enabled var-swap-swapfile.swap | grep -q enabled"
chk "systemd-oomd masked (single OOM killer)" bash -c "chroot '$R' systemctl is-enabled systemd-oomd.service | grep -qx masked && chroot '$R' systemctl is-enabled systemd-oomd.socket | grep -qx masked"
chk "earlyoom args: prefer/avoid set, no quotes/backslashes" bash -c ". '$R/etc/default/earlyoom'; [[ \$EARLYOOM_ARGS == *--prefer* && \$EARLYOOM_ARGS == *--avoid* && \$EARLYOOM_ARGS != *[\\\"\\'\\\\]* ]]"
chk "earlyoom regexes compile (POSIX ERE) and classify" bash -c ". '$R/etc/default/earlyoom'; read -ra a <<<\"\$EARLYOOM_ARGS\"; for i in \${!a[@]}; do [[ \${a[i]} == --prefer ]] && P=\${a[i+1]}; [[ \${a[i]} == --avoid ]] && A=\${a[i+1]}; done; for n in Hades.exe Cyberpunk2077.e wine64-preloade FEXInterpreter steamwebhelper; do echo \$n | grep -Eq \"\$P\" || exit 1; echo \$n | grep -Eq \"\$A\" && exit 1; done; for n in steam Xorg gamescope-wl sddm sshd systemd-journal; do echo \$n | grep -Eq \"\$A\" || exit 1; echo \$n | grep -Eq \"\$P\" && exit 1; done; exit 0"
chk "earlyoom binary supports --prefer/--avoid" bash -c "strings '$R/usr/bin/earlyoom' | grep -q -- '--prefer REGEX' && strings '$R/usr/bin/earlyoom' | grep -q -- '--avoid REGEX'"
chk "OOMScoreAdjust ssh=-900 sddm=-500 earlyoom=-1000" bash -c "grep -qx 'OOMScoreAdjust=-900' '$R/etc/systemd/system/ssh.service.d/10-steamos-orin-oom.conf' && grep -qx 'OOMScoreAdjust=-500' '$R/etc/systemd/system/sddm.service.d/10-steamos-orin-oom.conf' && grep -qx 'OOMScoreAdjust=-1000' '$R/etc/systemd/system/earlyoom.service.d/10-steamos-orin.conf'"
chk "steam client launched at oom_score_adj -200" grep -q 'choom -n -200' "$R/usr/lib/steamos-orin/steam-launch"
chk "oom-tagger rule table (steam -200, webhelper +300, games +500, gamescope -500)" python3 "$HERE/scripts/test-oom-tagger.py" "$R/usr/lib/steamos-orin/oom-tagger"
chk "oom-tagger python syntax (chroot python3)" bash -c "chroot '$R' python3 -c 'import ast,sys;ast.parse(open(\"/usr/lib/steamos-orin/oom-tagger\").read())'"
chk "sysctl memory values" bash -c "f='$R/etc/sysctl.d/99-steamos-orin-memory.conf'; for kv in 'vm.swappiness = 180' 'vm.page-cluster = 0' 'vm.watermark_scale_factor = 125' 'vm.watermark_boost_factor = 0' 'vm.min_free_kbytes = 65536'; do grep -qx \"\$kv\" \"\$f\" || exit 1; done"
chk "no other sysctl.d file overrides vm.* memory keys" bash -c "! grep -rlE '^\s*vm\.(swappiness|page-cluster|watermark_scale_factor|watermark_boost_factor|min_free_kbytes)' '$R/etc/sysctl.d' '$R/usr/lib/sysctl.d' '$R/etc/sysctl.conf' 2>/dev/null | grep -v 99-steamos-orin-memory.conf | grep -q ."
chk "zram priority 100 > swapfile priority 10" bash -c "grep -qx 'swap-priority = 100' '$R/etc/systemd/zram-generator.conf' && grep -qx 'Priority=10' '$R/etc/systemd/system/var-swap-swapfile.swap'"
chk "swapfile NOT in image (created at first boot)" bash -c "[ ! -e '$R/var/swap/swapfile' ]"
chk "make-swapfile creates a valid swapfile (box test, 32 MiB)" bash -c "d=\$(mktemp -d); SWAPFILE=\$d/s/swapfile SWAP_SIZE_MB=32 bash '$R/usr/lib/steamos-orin/make-swapfile' >/dev/null && blkid -p -o value -s TYPE \$d/s/swapfile | grep -qx swap && [ \$(stat -c %a \$d/s/swapfile) = 600 ]; r=\$?; rm -rf \$d; exit \$r"
chk "journald persistent (OOM kills survive reboot)" grep -qx 'Storage=persistent' "$R/etc/systemd/journald.conf.d/10-steamos-orin.conf"
chk "steamos can read system journal (adm group)" bash -c "chroot '$R' id -nG steamos | grep -qw adm"
chk "p0-checklist reports OOM kills" grep -q 'OOM kills' "$HERE/scripts/p0-checklist.sh"
if command -v shellcheck >/dev/null; then
  chk "shellcheck overlay + build scripts" shellcheck -x "$HERE/build.sh" "$HERE"/scripts/*.sh \
     "$R"/usr/lib/steamos-orin/steam-* "$R/usr/lib/steamos-orin/set-maxn-super" \
     "$R"/usr/lib/steamos-orin/{firstboot-setup,oneshot-desktop,session-reset-boot,session-oneshot-reset,wait-for-clock} \
     "$R/usr/bin/steamos-session-select" "$R"/usr/bin/steamos-polkit-helpers/* \
     "$R/usr/bin/steamos-update" "$R/usr/bin/jupiter-biosupdate" \
     "$R/usr/lib/steamos-orin/make-swapfile" "$R/usr/bin/steamos-game-oom"
fi
echo; echo "validate: $pass passed, $fail failed"
[[ $fail -eq 0 ]]
